const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const htmlPath = '/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-vanilla-js--style-modern/gpt-5.5__s1/index.html';
  const html = fs.readFileSync(htmlPath, 'utf8');
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const scans = [];
  scans.push(['initial', await page.evaluate(async () => await window.axe.run())]);
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(100);
  scans.push(['after-submit-error', await page.evaluate(async () => await window.axe.run())]);
  await browser.close();

  let failed = false;
  const summary = scans.map(([scan, result]) => {
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    const bestPractice = result.violations.filter((v) => v.tags.includes('best-practice'));
    if (wcag.length) failed = true;
    return {
      scan,
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      best_practice: bestPractice.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  });
  console.log(JSON.stringify(summary, null, 2));
  process.exit(failed ? 1 : 0);
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
